# Note, this operation is not immune to race conditions, see: https://linux.die.net/man/2/fcntl
@contextmanager
def flock(fd):
    fcntl.flock(fd, fcntl.LOCK_EX)
    try:
        yield
    finally:
        fcntl.flock(fd, fcntl.LOCK_UN)

