free -g | head -2; cd /tmp && timeout 300 python3 -I -c "
import io, struct, random, hashlib, time, statistics
def orig():
    payload = io.BytesIO()
    for i in range(1024):
        payload.write(struct.pack(b'L', random.getrandbits(64))*64*1024)
    p = payload.getvalue()
    return p, hashlib.md5(p).hexdigest()
def repl():
    p = b''.join(struct.pack(b'L', random.getrandbits(64))*64*1024 for i in range(1024))
    return p, hashlib.md5(p).hexdigest()
random.seed(7); a, ha = orig()
random.seed(7); b, hb = repl()
print('identical bytes', a == b, 'md5 equal', ha == hb, 'size', len(a))
del a, b
for name, f in (('orig', orig), ('repl', repl)):
    ts = []
    for r in range(3):
        t0 = time.perf_counter(); f(); ts.append(time.perf_counter() - t0)
    print(name, 'median s', round(statistics.median(ts), 3), 'runs', [round(x,3) for x in ts])
"

